CREATE OR REPLACE PROCEDURE dswtdir2_globe_dbo.sp_mybss_globe_eom_preload_dp5_export_unconfirmed_msf_loadfiles(INOUT p_refcur refcursor)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
    OPEN p_refcur FOR
    SELECT
        'batch no', 'Doc. Date', 'Post Date', 'Doc. Type', 'Co. Code', 'Currency', 'Translation Date', 'Period', 'Reference', 'Doc.Hdr.Text', 'Posting Key', 'Spcl GL indicator', 'GL/SL code', 'Reconciliation G/L account', 'Amount', 'Tax Code', 'IO number', 'Cost Center', 'Profit Center', 'Assign.', 'Text ', 'Rate', 'Trading Partner', 'Partner profit center', 'Quantity', 'UoM', 'BRAND', 'Sub-product A', 'sub-product B', 'Franchise Area', 'Business Centre', 'Revenue/Sales Type', 'Event/Segment', 'Payment Term', 'Payment Method', 'MVNO PARTNER', 'TECHNOLOGY', 'PLAN TYPE', 'CORE PRODUCT', 'REVENUE ITEM CODE', 'zDSP_order', 'zDSP_UniqueKey'
    UNION ALL
    SELECT
        etl_db_dbo.fn_cleantxt("batch no"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("Doc. Date"), etl_db_dbo.fn_cleantxt("Post Date"), etl_db_dbo.fn_cleantxt("Doc. Type"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("Co. Code"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt(currency::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("Translation Date"), etl_db_dbo.fn_cleantxt(period), etl_db_dbo.fn_cleantxt(reference::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("Doc.Hdr.Text"), etl_db_dbo.fn_cleantxt("Posting Key"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("Spcl GL indicator"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("GL/SL code"), etl_db_dbo.fn_cleantxt("Reconciliation G/L account"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt(CAST (amount AS VARCHAR(255))), etl_db_dbo.fn_cleantxt("Tax Code"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("IO number"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("Cost Center"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("Profit Center"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("Assign."::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("Text "), etl_db_dbo.fn_cleantxt(rate::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("Trading Partner"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("Partner profit center"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt(quantity::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt(uom::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt(brand), etl_db_dbo.fn_cleantxt("Sub-product A"), etl_db_dbo.fn_cleantxt("sub-product B"), etl_db_dbo.fn_cleantxt("Franchise Area"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("Business Centre"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("Revenue/Sales Type"), etl_db_dbo.fn_cleantxt("Event/Segment"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("Payment Term"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("Payment Method"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("MVNO PARTNER"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt(technology::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("PLAN TYPE"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("CORE PRODUCT"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt("REVENUE ITEM CODE"::NUMERIC(18, 0)), etl_db_dbo.fn_cleantxt(CAST (zdsp_order AS VARCHAR(255))), etl_db_dbo.fn_cleantxt(zdsp_uniquekey)
        FROM dswtdir2_globe_dbo.txglobe_dp5_unconfirmed_msf_expsel;
END;
$procedure$
